@Service
public class BankService {
    private final AccountRepository accountRepo;

    @Transactional  // Provides all ACID properties
    public void transferMoney(Long fromId, Long toId, BigDecimal amount) {
        var fromAccount = accountRepo.findById(fromId)
            .orElseThrow(() -> new AccountNotFoundException(fromId));
        var toAccount = accountRepo.findById(toId)
            .orElseThrow(() -> new AccountNotFoundException(toId));

        if (fromAccount.balance().compareTo(amount) < 0) {
            throw new InsufficientFundsException();  // Atomicity: entire transaction rolls back
        }

        fromAccount.withdraw(amount);  // Isolation: other transactions see old or new balance, never intermediate
        toAccount.deposit(amount);

        accountRepo.save(fromAccount);  // Consistency: constraints checked before commit
        accountRepo.save(toAccount);    // Durability: changes survive crash after commit
    }
}

@Service
public class OrderService {
    private final OrderRepository orderRepo;
    private final InventoryService inventoryService;
    private final PaymentService paymentService;

    @Transactional  // Atomicity: all steps commit together or all roll back
    public Order placeOrder(Long userId, List<Long> productIds) {
        var order = new Order(userId, LocalDateTime.now());
        orderRepo.save(order);  // Step 1: create order record

        for (Long productId : productIds) {
            inventoryService.reserveStock(productId, 1);  // Step 2: reserve inventory
        }

        paymentService.charge(userId, order.totalAmount());  // Step 3: charge payment

        // If payment throws PaymentFailedException, entire transaction rolls back:
        // - order record deleted
        // - inventory reservations undone
        // - user sees no order in their history

        return order;  // Commit happens here if no exception
    }
}

@Service
public class PaymentService {
    private final PaymentRepository paymentRepo;
    private final AuditLogRepository auditRepo;

    @Transactional
    public Payment processPayment(Long userId, BigDecimal amount) {
        var payment = new Payment(userId, amount, LocalDateTime.now(), "SUCCESS");
        paymentRepo.save(payment);  // Written to WAL before commit

        auditRepo.save(new AuditLog("PAYMENT", userId, amount));

        // When method returns, Spring commits the transaction
        // Commit forces WAL to flush to disk (fsync)
        // Even if server crashes 1 second later, payment survives
        return payment;
    }

    // Later, after crash and recovery:
    // Database replays WAL to restore committed payment and audit log
    // Uncommitted transactions are discarded using undo log

    public Optional<Payment> getPayment(Long id) {
        return paymentRepo.findById(id);  // Will find payment because it's durable
    }
}

@Service
public class BankTransferService {
    private final AccountRepository accountRepo;
    private final TransactionLogRepository logRepo;

    @Transactional(isolation = Isolation.SERIALIZABLE)  // Prevent race conditions
    public TransferResult transfer(Long fromId, Long toId, BigDecimal amount) {
        // CONSISTENCY: Constraint checks (amount > 0, accounts exist)
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
        }

        var fromAccount = accountRepo.findById(fromId).orElseThrow();
        var toAccount = accountRepo.findById(toId).orElseThrow();

        // ISOLATION: Serializable prevents concurrent transfers from double-spending
        if (fromAccount.getBalance().compareTo(amount) < 0) {
            throw new InsufficientFundsException();  // ATOMICITY: entire transaction rolls back
        }

        fromAccount.withdraw(amount);  // ATOMICITY: both debit and credit must succeed
        toAccount.deposit(amount);

        accountRepo.save(fromAccount);
        accountRepo.save(toAccount);

        logRepo.save(new TransactionLog(fromId, toId, amount, LocalDateTime.now()));
        // DURABILITY: once committed, transfer survives crash
        return new TransferResult("SUCCESS", amount);
    }
}

@Service
public class InventoryService {
    private final ProductRepository productRepo;

    @Transactional
    public void adjustStock(Long productId, int quantity) {
        var product = productRepo.findById(productId).orElseThrow();
        product.setStockLevel(product.getStockLevel() + quantity);
        productRepo.save(product);

        // Behind the scenes (database internals):
        // 1. Change (product ID, old stock, new stock) written to WAL
        // 2. WAL flushed to disk (fsync)
        // 3. COMMIT returns to application
        // 4. Data page updated in memory (may not be flushed yet)

        // Crash scenario:
        // If server crashes after step 3 but before step 4,
        // data page is lost but WAL survives.
        // On recovery, database replays WAL (REDO) to restore stock change.
    }

    // Recovery process (simplified):
    // for each record in WAL:
    //     if transaction committed: REDO (reapply change to data pages)
    //     if transaction not committed: UNDO (reverse change using undo log)
}
